func verdictClass(verdict models.Verdict) string {
	switch verdict {
	case "go":
		return "is-go"
	case "caution":
		return "is-caution"
	default:
		return "is-no-go"
	}
}

func verdictLabel(verdict models.Verdict) string {
	switch verdict {
	case "go":
		return "Можно выходить"
	case "caution":
		return "Осторожно"
	default:
		return "Не рекомендуется"
	}
}

